// @ts-ignore - no types available for html5sortable
import sortable from 'html5sortable/dist/html5sortable.es.js';
import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import PolicyEdit from './PolicyEdit';
import sortByAttribute from '../../common/helpers/sortByAttribute';
export default class PolicyList extends Component {
  oninit(vnode) {
    super.oninit(vnode);

    // Use JSON:API store to fetch policies
    app.store.find('fof-terms-policies').then(() => {
      m.redraw();
    });
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    this.initsortable(vnode);
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    // We could do this without re-creating the sortable on every redraw, but the current system works well
    // "If it ain't broken, don't fix it"
    this.initsortable(vnode);
  }
  initsortable(vnode) {
    const container = vnode.dom.querySelector('.js-policies-container');
    if (container) {
      sortable(container, {
        handle: '.js-policy-handle'
      })[0].addEventListener('sortupdate', () => {
        const sorting = Array.from(vnode.dom.querySelectorAll('.js-policy-data')).map(element => element.dataset.id);
        this.updateSort(sorting);
      });
    }
  }
  view() {
    const policies = app.store.all('fof-terms-policies');
    const fieldsList = sortByAttribute(policies).map(policy => m("div", {
      className: "js-policy-data",
      key: policy.id(),
      "data-id": policy.id()
    }, m(PolicyEdit, {
      policy: policy
    })));
    return m("div", null, m("h2", null, app.translator.trans('fof-terms.admin.titles.policies')), m("div", {
      className: "FoF-Terms-Policies-Container"
    }, m("div", {
      className: "js-policies-container"
    }, fieldsList), m(PolicyEdit, {
      policy: null
    })));
  }
  updateSort(sorting) {
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/fof/terms/policies/order',
      body: {
        sort: sorting
      }
    }).then(result => {
      // Update sort attributes
      app.store.pushPayload(result);
      m.redraw();
    });
  }
}
flarum.reg.add('fof-terms', 'admin/components/PolicyList', PolicyList);